#!/bin/bash
# Auto-generated by setup.py — do not edit manually
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
VENV_DIR="${SCRIPT_DIR}/venv"
INSTALL_DIR="${SCRIPT_DIR}/install"

if [ -d "${VENV_DIR}" ]; then
  source "${VENV_DIR}/bin/activate"
else
  echo "Warning: venv not found at ${VENV_DIR}" >&2
fi

# XRT environment
if [ -f /opt/xilinx/xrt/setup.sh ]; then
  # shellcheck disable=SC1091
  source /opt/xilinx/xrt/setup.sh
fi

# Vitis environment (detected during setup)
if [ -z "${VITIS:-}" ]; then
  export VITIS="/opt/ryzen_ai-1.3.0.1/vitis_aie_essentials"
fi

# llvm-aie (Peano) — built from source into install/llvm-aie by build.sh.
# Provides the Peano AIE compiler and the RTTI-enabled LLVM for llvmlite/PythoC.
export PEANO_INSTALL_DIR="${INSTALL_DIR}/llvm-aie"
LLVM_AIE_INSTALL_DIR="${INSTALL_DIR}/llvm-aie"
if [ -d "${LLVM_AIE_INSTALL_DIR}" ]; then
  export LLVM_AIE_INSTALL_DIR
  export LLVM_CONFIG="${LLVM_AIE_INSTALL_DIR}/bin/llvm-config"
  # Build llvmlite against llvm-aie: skip the version check, enable RTTI.
  export LLVMLITE_SKIP_LLVM_VERSION_CHECK=1
  export LLVMLITE_USE_RTTI=ON
fi

# Add toolchain bins to PATH if present
for d in "${INSTALL_DIR}/llvm/bin" "${INSTALL_DIR}/llvm-aie/bin" "${INSTALL_DIR}/mlir-aie/bin" "${INSTALL_DIR}/mlir-air/bin" "${INSTALL_DIR}/triton-xdna/bin"; do
  [ -d "${d}" ] && case ":$PATH:" in *:"${d}":*) ;; *) PATH="${d}:$PATH";; esac
done

# Add Vitis tools to PATH if VITIS is set
if [ -n "${VITIS:-}" ]; then
  for d in "${VITIS}/aietools/bin" "${VITIS}/bin"; do
    [ -d "${d}" ] && case ":$PATH:" in *:"${d}":*) ;; *) PATH="${PATH}:${d}";; esac
  done
fi

export PATH

# Add MLIR-AIE / MLIR-AIR python packages to PYTHONPATH if present
for d in "${INSTALL_DIR}/mlir-air/python" "${INSTALL_DIR}/mlir-aie/python"; do
  [ -d "${d}" ] && case ":${PYTHONPATH:-}:" in *:"${d}":*) ;; *) PYTHONPATH="${d}${PYTHONPATH:+:$PYTHONPATH}";; esac
done
export PYTHONPATH

# Add shared library dirs to LD_LIBRARY_PATH if present
for d in "${INSTALL_DIR}/mlir/lib" "${INSTALL_DIR}/mlir-air/lib" "${INSTALL_DIR}/mlir-aie/lib"; do
  [ -d "${d}" ] && case ":${LD_LIBRARY_PATH:-}:" in *:"${d}":*) ;; *) LD_LIBRARY_PATH="${d}${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}";; esac
done
export LD_LIBRARY_PATH
